        keyCustody: String? = nil,
        keyLocator: String? = nil,
        mtlsTrustAnchor: Bool? = nil,
        notAfter: String,
        notBefore: String,
        organizationID: String,
        parentCAID: String? = nil,
        publicCertPEM: String,
        status: CertificateStatus,
        subject: String,
        tenantID: String? = nil,
        privateKeyPEM: Sensitive<String>? = nil
    ) {
        self.chainPEM = chainPEM
        self.createdAt = createdAt
        self.fingerprint = fingerprint
        self.id = id
        self.keyAlgorithm = keyAlgorithm
        self.keyCustody = keyCustody
        self.keyLocator = keyLocator
        self.mtlsTrustAnchor = mtlsTrustAnchor
        self.notAfter = notAfter
        self.notBefore = notBefore
        self.organizationID = organizationID
        self.parentCAID = parentCAID
        self.publicCertPEM = publicCertPEM
        self.status = status
        self.subject = subject
        self.tenantID = tenantID
