/// X4 trust for exchanging this provider's tokens (RFC 8693, external issuer). Mirrors
/// [`TokenExchangeTrust`] on the wire rather than reusing it directly so the API surface can
/// carry its own defaults: an admin PUTting a partial block gets the documented default for
/// anything they omitted, instead of a deserialization error listing fields they have never
/// heard of.
public struct TokenExchangeTrustRequest: Codable, Sendable {
    /// Audiences an incoming subject token may name. Required (non-empty) when `enabled`; there
    /// is deliberately no accept-all value.
    public let acceptedAudiences: [String]?

    /// Off unless explicitly enabled. Configuring a provider for *login* is not agreement to
    /// accept its tokens as API credentials.
    public let enabled: Bool?

    /// Per-provider ceiling on the issued AXIAM token's lifetime.
    public let maxLifetimeSecs: Int?

    /// Bound on `now - iat`, independent of the token's own `exp`.
    public let maxTokenAgeSecs: Int?

    /// External asserted value -> AXIAM scopes. Deny-by-default: an external value with no
    /// entry contributes nothing.
    public let scopeMap: ManagementJSON?

    /// `linked_only` (default) or `jit_provision`.
    public let subjectMapping: String?

    public init(
        acceptedAudiences: [String]? = nil,
        enabled: Bool? = nil,
        maxLifetimeSecs: Int? = nil,
        maxTokenAgeSecs: Int? = nil,
        scopeMap: ManagementJSON? = nil,
        subjectMapping: String? = nil
    ) {
        self.acceptedAudiences = acceptedAudiences
        self.enabled = enabled
        self.maxLifetimeSecs = maxLifetimeSecs
        self.maxTokenAgeSecs = maxTokenAgeSecs
        self.scopeMap = scopeMap
        self.subjectMapping = subjectMapping
    }

    enum CodingKeys: String, CodingKey {
        case acceptedAudiences = "accepted_audiences"
        case enabled = "enabled"
        case maxLifetimeSecs = "max_lifetime_secs"
        case maxTokenAgeSecs = "max_token_age_secs"
        case scopeMap = "scope_map"
        case subjectMapping = "subject_mapping"
    }

    public init(from decoder: any Decoder) throws {
        let container = try decoder.container(keyedBy: CodingKeys.self)
        self.acceptedAudiences = try container.decodeIfPresent([String].self, forKey: .acceptedAudiences)
