        self.maxTokenAgeSecs = try container.decodeIfPresent(Int.self, forKey: .maxTokenAgeSecs)
        self.scopeMap = try container.decodeIfPresent(ManagementJSON.self, forKey: .scopeMap)
        self.subjectMapping = try container.decodeIfPresent(String.self, forKey: .subjectMapping)
