/// Per-tenant WebAuthn attestation policy (D5). One row per tenant; an absent row means
/// [`WebauthnAttestationPolicy::default`], which is today's behavior unchanged.
public struct WebauthnAttestationPolicy: Codable, Sendable {
    /// `None` = every AAGUID is allowed except `blocked_aaguids`. `Some(vec![])` is a
    /// deliberate "nothing may register" policy and is accepted as such: `evaluate` denies
    /// every AAGUID against an empty allow-list. Nothing rejects it, precisely because the
    /// failure direction is safe — a client that sends `[]` when it meant `null` gets a
    /// locked-down tenant, which is visible immediately, rather than an open one, which is not.
    public let allowedAaguids: [String]?

    /// Deny registration if the MDS entry has ever reported `REVOKED` or any `*_COMPROMISE`
    /// status (sticky — D8 step 7).
    public let blockRevokedStatus: Bool

    /// The server's `blocked_aaguids` field.
    public let blockedAaguids: [String]?

    /// The server's `min_certification` field.
    public let minCertification: CertificationLevel?

    /// The server's `mode` field.
    public let mode: AttestationMode

    /// Require *some* `FIDO_CERTIFIED*` status, any level. Independent of (and checked before)
    /// `min_certification`.
    public let requireFidoCertified: Bool

    /// The server's `unknown_aaguid` field.
